-- Space EI: give Claude Code the project context: .mcp.json (ESP-IDF tools, component registry,
-- Espressif docs) and a CLAUDE.md block describing the board and how to build, flash and read output
local util = require("esp.util")
local board = require("esp.board")
local M = {}

local begin_marker =
  "<!-- esp-nvim:begin (generated by Neovim Space EI, edit outside these markers) -->"
local end_marker = "<!-- esp-nvim:end -->"
local capture = vim.fn.stdpath("config") .. "/bin/esp-capture"

local function read_json(path)
  local ok, data = pcall(function()
    return vim.json.decode(table.concat(vim.fn.readfile(path), "\n"))
  end)
  return ok and type(data) == "table" and data or {}
end

local function write_pretty_json(path, data)
  local res = vim
    .system({ "python3", "-I", "-m", "json.tool", "--indent", "2" }, {
      stdin = vim.json.encode(data),
      text = true,
    })
    :wait()
  vim.fn.writefile(
    vim.split(res.code == 0 and res.stdout or vim.json.encode(data), "\n", { trimempty = true }),
    path
  )
end

function M.write_mcp(root)
  local path = root .. "/.mcp.json"
  local data = read_json(path)
  data.mcpServers = data.mcpServers or {}
  data.mcpServers["esp-idf"] = {
    type = "stdio",
    command = "sh",
    args = { "-c", (util.idf_cmd("mcp-server"):gsub("python ", "exec python ", 1)) },
  }
  data.mcpServers["esp-component-registry"] =
    { type = "http", url = "https://components.espressif.com/mcp" }
  data.mcpServers["espressif-documentation"] =
    { type = "http", url = "https://mcp.espressif.com/docs" }
  write_pretty_json(path, data)
end

-- Chip revision as the board reported it in the last monitor session or capture
local function silicon_revision(root)
  for _, name in ipairs({ "monitor.log", "capture.log" }) do
    local ok, lines = pcall(vim.fn.readfile, root .. "/build/" .. name)
    for _, l in ipairs(ok and lines or {}) do
      local rev = l:match("silicon revision (v[%d.]+)")
      if rev then
        return rev
      end
    end
  end
end

local function claude_block(root)
  local target = util.sdkconfig_target(root)
  local port = board.port(root)
  local profile = board.profile(root)
  local rev = silicon_revision(root) or (profile.revision ~= vim.NIL and profile.revision or nil)
  if rev then
    profile = board.update_profile(root, { revision = rev, chip = target })
  end
  local usb = profile.usb ~= vim.NIL and profile.usb or nil
  local activate = util.activate_script() or "~/.espressif/tools/activate_idf_v*.sh"
  local version = activate:match("activate_idf_(v[%d.]+)%.sh") or "?"
  local p = port and (" -p " .. port) or ""
  return {
    begin_marker,
    "## ESP-IDF project",
    "",
    ("- Chip: %s%s, ESP-IDF %s (`%s`)"):format(
      target,
      rev and (" " .. rev) or "",
      version,
      util.idf_path() or "?"
    ),
    "- Serial port: "
      .. (port or "auto-detect (none chosen in Neovim yet)")
      .. (usb and (", USB id " .. usb) or ""),
    "- Board profile: `.esp-board.json` (port, USB id, chip, revision; set with Neovim Space Ep).",
    "- The user works in Neovim with this project; Claude Code runs in a split next to it.",
    "",
    "## Build, flash, read the board",
    "",
    "- Prefer the `esp-idf` MCP tools: `build_project`, `flash_project`, `set_target`, `clean_project`;",
    "  resources `project://status` and `project://devices`.",
    "- Shell commands need the ESP-IDF environment first:",
    ("  `. %s >/dev/null && idf.py%s build`"):format(activate, p),
    "- Device output: `build/monitor.log` is the user's current or last monitor session (clean text).",
    ("  To capture output yourself: `%s 15%s` (resets the chip, prints 15 s, saves build/capture.log)."):format(
      capture,
      port and (" " .. port) or ""
    ),
    "  If the port is busy, the user's monitor is open: read build/monitor.log instead.",
    "- Build errors and crash backtraces are diagnostics with source `esp-idf` (getDiagnostics).",
    "- After a crash with core dumps enabled: `idf.py coredump-info` (Neovim Space Ek saves it to",
    "  build/coredump.txt): crashed task, its stack, and all FreeRTOS tasks with stack usage.",
    ("- Hardware tests: `%s%s` builds, flashes and runs pytest_*.py (pytest-embedded) on the board."):format(
      vim.fn.stdpath("config") .. "/bin/esp-test",
      port and (" " .. port) or ""
    ),
    "",
    "## Libraries and docs",
    "",
    "- Find components with the `esp-component-registry` MCP server, add them with",
    '  `idf.py add-dependency "namespace/name^version"` (then rebuild).',
    "- `espressif-documentation` MCP is limited to 10 requests/hour: prefer the headers under",
    "  `$IDF_PATH/components` for API details.",
    "",
    "## Rules",
    "",
    "- Ask before: erase-flash, any efuse-* command, secure boot or flash encryption,",
    "  partition table changes, set-target (wipes build/).",
    "- Change configuration in `sdkconfig.defaults` (then `idf.py reconfigure`), not `sdkconfig`.",
    end_marker,
  }
end

function M.write_claude_md(root)
  local path = root .. "/CLAUDE.md"
  local block = claude_block(root)
  local ok, lines = pcall(vim.fn.readfile, path)
  lines = ok and lines or { "# " .. vim.fs.basename(root), "" }
  local s, e
  for i, l in ipairs(lines) do
    if l == begin_marker then
      s = i
    elseif l == end_marker then
      e = i
    end
  end
  if s and e then
    local out = vim.list_slice(lines, 1, s - 1)
    vim.list_extend(out, block)
    vim.list_extend(out, vim.list_slice(lines, e + 1))
    lines = out
  else
    if lines[#lines] ~= "" then
      lines[#lines + 1] = ""
    end
    vim.list_extend(lines, block)
  end
  vim.fn.writefile(lines, path)
end

function M.init_project()
  local root = util.project_root()
  if not vim.uv.fs_stat(root .. "/CMakeLists.txt") then
    return vim.notify("Not an ESP-IDF project: " .. root, vim.log.levels.ERROR)
  end
  M.write_mcp(root)
  M.write_claude_md(root)
  vim.notify(
    "Wrote .mcp.json and CLAUDE.md. In Claude Code: approve the project MCP servers, run /mcp to sign in to the docs server"
  )
end

return M
